import React, { useState, useMemo, useCallback } from 'react';

// Create the App component here
const App = () => {
  // Initialize state variables here
  const [counter, setCounter] = useState(0);
  const [inputValue, setInputValue] = useState('');

  // Create the expensiveCalculation function here
  const expensiveCalculation = (num) => {
    console.log('Calculating...');
    let result = 0;
    for (let i = 0; i < 1000000000; i++) {
      result += num;
    }
    return result;
  };

  // Create memoizedResult with useMemo here
  const memoizedResult = useMemo(() => expensiveCalculation(counter), [counter]);

  // Create event handlers for counter and input here
  const incrementCounter = () => {
    setCounter(counter + 1);
  };

  const handleInputChange = (e) => {
    setInputValue(e.target.value);
  };

  // Create a non-memoized callback function here
  const nonMemoizedCallback = () => {
    console.log('Non-memoized callback called');
  };

  // Create a memoized callback with useCallback here
  const memoizedCallback = useCallback(() => {
    console.log('Memoized callback called');
  }, []);

  return (
    <div>
      <h1>Memoization Strategy Demo</h1>
      <h2>Counter: {counter}</h2>
      <h2>Input Value: {inputValue}</h2>
    </div>
  );
};

